return function(import)
local RunService = game:GetService(S(18))
local log = import(S(303))
local SLICE_SECONDS = 3
local scheduler = {}
local tasks = {}
local connection = nil
local rrIndex = 0
local currentTask = nil
local sliceEnd = 0
function scheduler.Register(name, step, isEnabled, isBusy)
    table.insert(tasks, { name = name, step = step, isEnabled = isEnabled, isBusy = isBusy })
end
local function anyBusy()
    for _, task_ in ipairs(tasks) do
        if task_.isBusy and task_.isBusy() then
            return true
        end
    end
    return false
end
local function pickNextEnabled()
    if #tasks == 0 then
        return nil
    end
    for _ = 1, #tasks do
        rrIndex = (rrIndex % #tasks) + 1
        local candidate = tasks[rrIndex]
        if candidate.isEnabled() then
            return candidate
        end
    end
    return nil
end
function scheduler.Start()
    if connection then
        return
    end
    connection = RunService.Heartbeat:Connect(function()
        if anyBusy() then
            return
        end
        local now = tick()
        if not currentTask or not currentTask.isEnabled() or now > sliceEnd then
            local next_ = pickNextEnabled()
            if next_ ~= currentTask then
                currentTask = next_
                log(S(285) .. (currentTask and currentTask.name or S(57)))
            end
            sliceEnd = now + SLICE_SECONDS
        end
        if currentTask then
            local ok, err = pcall(currentTask.step)
            if not ok then
                log(S(470) .. currentTask.name .. S(90) .. tostring(err))
            end
        end
    end)
end
function scheduler.Stop()
    if connection then
        connection:Disconnect()
        connection = nil
    end
    currentTask = nil
end
return scheduler
end
end
