modules[S(125)] = function()
return function(import)
local Players = game:GetService(S(403))
local getCurrentPlot = import(S(86))
local getPlotParts = import(S(417))
local teleport = import(S(416))
local click = import(S(364))
local log = import(S(431))
local CHECK_INTERVAL = 3
local MIN_ITEMS_TO_COLLECT = 100
local function getChestFrame()
    local playerGui = Players.LocalPlayer:FindFirstChild(S(44))
    local mineGui = playerGui and playerGui:FindFirstChild(S(410))
    return mineGui and mineGui:FindFirstChild(S(302))
end
local function getTakeButton(chestFrame)
    local content = chestFrame and chestFrame:FindFirstChild(S(173))
    local actions = content and content:FindFirstChild(S(131))
    return actions and actions:FindFirstChild(S(258))
end
local function parseCount(text)
    local digits = tostring(text):gsub(S(101), S(328)):match(S(260))
    return tonumber(digits)
end
local function getChestCount()
    local plot = getCurrentPlot()
    local parts = plot and getPlotParts(plot)
    local chest = parts and parts.Chest
    local amount = chest and chest:FindFirstChild(S(495), true)
    return amount and parseCount(amount.Text)
end
local function getItemCount(chestFrame)
    local content = chestFrame:FindFirstChild(S(170))
    local progress = content and content:FindFirstChild(S(377))
    local label = progress and progress:FindFirstChild(S(392))
    return parseCount(label and label.Text or S(62))
end
local function clickButton(button)
    local ok, err = click.Real(button)
    if not ok then
        log(S(175) .. button.Name .. S(1) .. tostring(err))
    end
    return ok
end
local function getChestPrompt()
    local plot = getCurrentPlot()
    local parts = plot and getPlotParts(plot)
    return parts and parts.Chest and parts.Chest:FindFirstChildWhichIsA(S(268), true)
end
local autoChest = {}
local enabled = false
local busy = false
local lastAttempt = 0
local lastReportedCount = nil
function autoChest.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    if not enabled then
        if not busy then
            teleport.Return()
        end
        log(S(144))
    else
        lastAttempt = 0
        lastReportedCount = nil
        log(S(212) .. MIN_ITEMS_TO_COLLECT .. S(450))
    end
end
function autoChest.IsEnabled()
    return enabled
end
function autoChest.IsBusy()
    return busy
end
local function runJob()
    busy = true
    local prompt = getChestPrompt()
    if not prompt then
        busy = false
        return
    end
    teleport.To(prompt.Parent)
    local ok, err = pcall(function()
        fireproximityprompt(prompt, Enum.ProximityPromptInputType.Keyboard, prompt.HoldDuration)
    end)
    if not ok then
        log(S(148) .. tostring(err))
        teleport.Return()
        busy = false
        return
    end
    task.wait(0.8)
    if not enabled then
        teleport.Return()
        busy = false
        return
    end
    local chestFrame = getChestFrame()
    if not (chestFrame and chestFrame.Visible) then
        log(S(489))
        teleport.Return()
        busy = false
        return
    end
    local count = getItemCount(chestFrame)
    local takeButton = getTakeButton(chestFrame)
    if takeButton then
        clickButton(takeButton)
        task.wait(0.6)
        local after = getItemCount(chestFrame)
        if after and count and after < count then
            log(S(276) .. count .. S(483) .. after .. S(304))
        else
            log(S(20) .. tostring(count)
                .. S(477) .. tostring(after) .. S(352))
        end
    end
    teleport.Return()
    busy = false
end
function autoChest.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < CHECK_INTERVAL then
        return
